package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.service.content.ReportInputProfile;
import com.lianxibu.site.service.jobs.GenerationFlowService.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;

/** Each route has actual native complete input providers; its unused route is an explicit no-I/O mock. Source/model genesis is fictional. */
class ReportInputCaptureTest {
    boolean mysql(){return false;}
    DailyReportInputComponentTest daily()throws Exception{var f=new DailyReportInputComponentTest(){@Override boolean mysql(){return ReportInputCaptureTest.this.mysql();}};f.nativeSetup("agent");return f;}
    ReportPeriodProofNativeTest period(){var f=mysql()?new ReportPeriodProofNativeMySqlTest():new ReportPeriodProofNativeTest();f.setup();return f;}
    <T>T rr(PlatformTransactionManager manager,java.util.function.Supplier<T> work){var tx=new TransactionTemplate(manager);tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);return tx.execute(s->work.get());}
    Prepare command(ReportInputCaptureService.Captured c){var scope=c.scope();return new Prepare(scope.logicalKey(),scope.generation(),scope.stage(),scope.day(),null,c.dependencies(),List.of(),c.dependencies().stream().map(Dependency::id).toList(),false,"a".repeat(64));}
    @Test void ActualDailyFourGroupRoutePreservesWholeOriginalBodyDependenciesAndReferences()throws Exception{var f=daily();var tx=f.data.nativeData().fixture().f().tx;var unused=mock(ReportPeriodInputComponentService.class);var service=new ReportInputCaptureService(f.service,unused,tx);var day=f.data.nativeData().fixture().day();var scope=new ReportInputCaptureService.Scope("report:daily:"+day,1,Stage.DAILY_REPORT,day);var c=service.capture(scope,f.data.nativeData().cutoff());assertNotNull(c);assertEquals(1,c.sourceProof().candidates().size());assertEquals(1,c.referenceTargetsByEvidence().size());assertEquals(1,c.dependencies().size());var frozen=rr(tx,()->new ReportInputSnapshotService(service.asReadonlySource(c)).freeze(command(c),c.cutoff()));ReportInputProfile.validated(CanonicalJson.parse(frozen.snapshotJson()));assertEquals("complete",frozen.coverageState());assertTrue(frozen.hasContent());assertEquals(2,f.data.nativeData().fixture().f().sends);assertSame(c,rr(tx,()->service.verifyObserved(c)));assertThrows(UnsupportedOperationException.class,()->c.referenceTargetsByEvidence().values().iterator().next().clear());verifyNoInteractions(unused);}
    @Test void ActualPeriodNativeClosureRouteKeepsSixMissingDatesAndNeverCreatesNoUpdateEvidence(){var f=period();var tx=f.f.h.h.f.tx;var unused=mock(DailyReportInputComponentService.class);var service=new ReportInputCaptureService(unused,f.service,tx);var scope=new ReportInputCaptureService.Scope("report:weekly:"+ReportPeriodInputComponentTest.LAST,1,Stage.WEEKLY_REPORT,ReportPeriodInputComponentTest.LAST);var c=service.capture(scope,ReportPeriodInputComponentTest.CUTOFF);assertEquals(1,c.sourceProof().candidates().size());assertEquals(6,c.sourceProof().missingInputs().size());assertTrue(c.sourceProof().noUpdateDates().isEmpty());var frozen=rr(tx,()->new ReportInputSnapshotService(service.asReadonlySource(c)).freeze(command(c),c.cutoff()));assertEquals("partial",frozen.coverageState());assertEquals(6,CanonicalJson.parse(frozen.snapshotJson()).get(ReportInputProfile.FIELD).get("coverage").get("missing_dates").size());assertEquals(1,f.f.h.h.f.sends);assertFalse(c.toString().contains("Fictional"));verifyNoInteractions(unused);}
    @Test void ChangedNativeDailyMetadataAndDifferentIssuerOrScopeRejectTheWholeCapture()throws Exception{var f=daily();var tx=f.data.nativeData().fixture().f().tx;var unused=mock(ReportPeriodInputComponentService.class);var service=new ReportInputCaptureService(f.service,unused,tx);var day=f.data.nativeData().fixture().day();var c=service.capture(new ReportInputCaptureService.Scope("report:daily:"+day,1,Stage.DAILY_REPORT,day),f.data.nativeData().cutoff());var foreign=new ReportInputCaptureService(f.service,unused,tx);assertThrows(RuntimeException.class,()->foreign.asReadonlySource(c));assertThrows(RuntimeException.class,()->rr(tx,()->foreign.verifyObserved(c)));var wrong=new Prepare(c.scope().logicalKey(),2,c.scope().stage(),c.scope().day(),null,List.of(),List.of(),List.of(),false,"a".repeat(64));assertThrows(RuntimeException.class,()->rr(tx,()->service.asReadonlySource(c).snapshot(wrong,c.cutoff())));f.data.nativeData().fixture().f().jdbc.update("UPDATE contents SET state='blocked' WHERE id=?",f.data.nativeData().completed().version().contentId());assertThrows(RuntimeException.class,()->rr(tx,()->service.verifyObserved(c)));var fresh=service.capture(c.scope(),c.cutoff());assertTrue(fresh.sourceProof().candidates().getFirst().evidence().blocked());}
    @Test void NoUnknownDailyFallbackAndReadonlyCallbackCannotBeUsedByTheExistingWriter(){var d=mock(DailyReportInputComponentService.class);var p=mock(ReportPeriodInputComponentService.class);var tx=mock(PlatformTransactionManager.class);var service=new ReportInputCaptureService(d,p,tx);verifyNoInteractions(d,p,tx);var day=LocalDate.parse("2026-01-01");var scope=new ReportInputCaptureService.Scope("report:daily:"+day,1,Stage.DAILY_REPORT,day);assertNull(service.capture(scope,day.plusDays(1).atTime(5,0).atZone(ZoneId.of("Asia/Shanghai")).toInstant()));verifyNoInteractions(p,tx);assertThrows(RuntimeException.class,()->new ReportInputCaptureService.Scope("fictional-alias",1,Stage.DAILY_REPORT,day));assertThrows(RuntimeException.class,()->new ReportInputCaptureService.Scope("report:daily:"+day,0,Stage.DAILY_REPORT,day));assertThrows(NullPointerException.class,()->new ReportInputCaptureService(d,null,tx));}
    @Test void ExplicitOwnedCaptureAndBorrowedReadonlyRrBoundariesHaveNoImplicitWriterBridge(){var f=period();var tx=f.f.h.h.f.tx;var service=new ReportInputCaptureService(mock(DailyReportInputComponentService.class),f.service,tx);var scope=new ReportInputCaptureService.Scope("report:weekly:"+ReportPeriodInputComponentTest.LAST,1,Stage.WEEKLY_REPORT,ReportPeriodInputComponentTest.LAST);var c=service.capture(scope,ReportPeriodInputComponentTest.CUTOFF);assertThrows(RuntimeException.class,()->service.asReadonlySource(c).snapshot(command(c),c.cutoff()));assertThrows(RuntimeException.class,()->rr(tx,()->service.capture(scope,c.cutoff())));var rc=new TransactionTemplate(tx);rc.setReadOnly(true);rc.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);assertThrows(RuntimeException.class,()->rc.execute(s->service.verifyObserved(c)));assertThrows(RuntimeException.class,()->f.f.h.h.f.writes.execute(f.f.h.h.f.action("fictional-report-capture-writer"),k->null,a->service.asReadonlySource(c).snapshot(command(c),c.cutoff())));assertSame(c,rr(tx,()->service.verifyObserved(c)));}
}
